import * as BufferLayout from "@solana/buffer-layout";
import { Ed25519Program, TransactionInstruction } from "@solana/web3.js";
var ED25519_INSTRUCTION_LEN = 16;
var SIGNATURE_LEN = 64;
var PUBKEY_LEN = 32;
var MAGIC_LEN = 4;
var MESSAGE_SIZE_LEN = 2;
var ED25519_INSTRUCTION_LAYOUT = BufferLayout.struct([
    BufferLayout.u8("numSignatures"),
    BufferLayout.u8("padding"),
    BufferLayout.u16("signatureOffset"),
    BufferLayout.u16("signatureInstructionIndex"),
    BufferLayout.u16("publicKeyOffset"),
    BufferLayout.u16("publicKeyInstructionIndex"),
    BufferLayout.u16("messageDataOffset"),
    BufferLayout.u16("messageDataSize"),
    BufferLayout.u16("messageInstructionIndex")
]);
export var createEd25519Instruction = function(message, instructionIndex, startingOffset) {
    var signatureOffset = startingOffset + MAGIC_LEN;
    var publicKeyOffset = signatureOffset + SIGNATURE_LEN;
    var messageDataSizeOffset = publicKeyOffset + PUBKEY_LEN;
    var messageDataOffset = messageDataSizeOffset + MESSAGE_SIZE_LEN;
    var messageDataSize = message.readUInt16LE(messageDataSizeOffset - startingOffset);
    var instructionData = Buffer.alloc(ED25519_INSTRUCTION_LEN);
    ED25519_INSTRUCTION_LAYOUT.encode({
        numSignatures: 1,
        padding: 0,
        signatureOffset: signatureOffset,
        signatureInstructionIndex: instructionIndex,
        publicKeyOffset: publicKeyOffset,
        publicKeyInstructionIndex: instructionIndex,
        messageDataOffset: messageDataOffset,
        messageDataSize: messageDataSize,
        messageInstructionIndex: instructionIndex
    }, instructionData);
    return new TransactionInstruction({
        keys: [],
        programId: Ed25519Program.programId,
        data: instructionData
    });
};
